import re
from pathlib import Path
from datetime import date, timedelta
from collections import Counter

as_of = date(2025, 8, 12)
severity_re = re.compile(r'\[([A-Z]+)\]')
severities = ['ERROR', 'WARNING', 'INFO']
allowed = set(severities)

records = []
for path in sorted(Path('/app/logs').glob('*.log')):
    for line in path.read_text().splitlines():
        match = severity_re.search(line)
        if not match:
            raise ValueError(f'Missing severity in {path.name}: {line}')
        severity = match.group(1)
        if severity not in allowed:
            continue
        event_date = date.fromisoformat(line.split(' ', 1)[0])
        records.append((event_date, severity))

def in_period(period, event_date):
    if period == 'today':
        return event_date == as_of
    if period == 'last_7_days':
        return as_of - timedelta(days=6) <= event_date <= as_of
    if period == 'last_30_days':
        return as_of - timedelta(days=29) <= event_date <= as_of
    if period == 'month_to_date':
        return date(2025, 8, 1) <= event_date <= as_of
    if period == 'total':
        return True
    return False

output = ['period,severity,count']
for period in ['today', 'last_7_days', 'last_30_days', 'month_to_date', 'total']:
    for severity in severities:
        count = sum(1 for event_date, event_severity in records if in_period(period, event_date) and event_severity == severity)
        output.append(f'{period},{severity},{count}')

Path('/app/summary.csv').write_text('\n'.join(output) + '\n')
